}', execution_details='Rename type references of `RestoreMode` to `RecoveryClaimMode` in method signatures, fields, and factory methods (`forPath(...)`), including imports.', refactoring_type=<SupportedRefactorings.RENAME: 'rename'>, file_path='flink-clients/src/main/java/org/apache/flink/client/cli/CliFrontendParser.java'), PlanningStep(reason='Update the CLI parser to import and reference the renamed enum when constructing restore settings.', final_code='import org.apache.flink.core.execution.RecoveryClaimMode;
...
public static SavepointRestoreSettings createSavepointRestoreSettings(CommandLine commandLine) {
    ...
    final RecoveryClaimMode claimMode;
    if (commandLine.hasOption(SAVEPOINT_CLAIM_MODE.getOpt())) {
        claimMode = ConfigurationUtils.convertValue(
            commandLine.getOptionValue(SAVEPOINT_CLAIM_MODE.getOpt()),
            RecoveryClaimMode.class);
    } else if (commandLine.hasOption(SAVEPOINT_RESTORE_MODE.getOpt())) {
        claimMode = ConfigurationUtils.convertValue(
            commandLine.getOptionValue(SAVEPOINT_RESTORE_MODE.getOpt()),
            RecoveryClaimMode.class);
        System.out.printf(
            "The option '%s' is deprecated. Please use '%s' instead.%n",
            SAVEPOINT_RESTORE_MODE.getLongOpt(), SAVEPOINT_CLAIM_MODE.getLongOpt());
